import{F as e,_ as t,f as n,g as r,h as i,j as a,l as o,n as s}from"./chunks/shared.rYHlazZf.js";var c=JSON.parse(`{"title":"Revise alterações por área","description":"","frontmatter":{"title":"Revise alterações por área","docId":"user.cloud.changes","translationKey":"user.cloud.changes","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"0bb2a29db86d989dfeb986bb696a9da4b7a47c942ecbdaa0a988f6bab501f12d","translationRevision":"156ccce61dd26f5505dafba4dfece46a03107f7bd22cedaadacb884a60263add","order":20},"headers":[],"relativePath":"pt/user/cloud/changes.md","filePath":"pt/user/cloud/changes.md","lastUpdated":1795731074000}`),l={name:`pt/user/cloud/changes.md`};function u(s,c,l,u,d,f){let p=e(`TourFrame`);return a(),n(`div`,null,[c[0]||=i(`<h1 id="review-changes-by-area" tabindex="-1">Revise alterações por área <a class="header-anchor" href="#review-changes-by-area" aria-label="Permalink to “Revise alterações por área”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Entenda o que um painel <strong>Changes</strong> compara antes de redefinir, enviar ou adotar dados. Você precisa de conteúdo local salvo. Operações do Cloud também precisam de um host compatível, do modo de sincronização relevante e de uma <a href="./account.html">conta autenticada</a>. Painéis com o mesmo nome não realizam todos o mesmo transporte.</p><h2 id="review-events-and-actions-locally" tabindex="-1">Revise Events e Actions localmente <a class="header-anchor" href="#review-events-and-actions-locally" aria-label="Permalink to “Revise Events e Actions localmente”">​</a></h2><ol><li>Abra <strong>Automations</strong>, selecione Events ou Actions e abra <strong>Changes</strong>.</li><li>Leia o aviso: essa área compara as definições atuais com uma referência mantida neste dispositivo. A primeira visita carregada inicializa essa referência, portanto pode legitimamente não mostrar alterações.</li><li>Selecione um registro adicionado, modificado ou excluído e inspecione os valores anteriores e posteriores.</li><li>Escolha <strong>Mark as reviewed</strong> somente quando quiser que a seção atual se torne a nova referência local. Isso não envia definições nem aprova execução delegada.</li><li>Use <strong>Reset</strong> apenas quando pretender restaurar a referência. Para um registro recém-adicionado, a redefinição o remove; para um registro modificado/excluído, ela restaura a definição mantida. Salve uma exportação antes, se necessário.</li></ol><p>O adaptador de Events/Actions não tem coleção do Cloud para definições individuais nesta versão. Uma comparação sem alterações não é um backup no Cloud nem prova de que outro computador recebeu suas edições.</p><h2 id="review-variables-and-plugins-explicitly" tabindex="-1">Revise Variables e Plugins explicitamente <a class="header-anchor" href="#review-variables-and-plugins-explicitly" aria-label="Permalink to “Revise Variables e Plugins explicitamente”">​</a></h2><p>Variables tem seu próprio compartilhamento nativo revisado: salve localmente, busque candidatas, inspecione a comparação e explicitamente envie, aplique/adote ou retire. Valores secretos ou bloqueados continuam mascarados e não podem ser enviados por esse caminho. Salvar localmente nunca envia. Consulte <a href="./../automations/variables.html">Variables</a>.</p><p>Changes de Plugins usa seu workspace de sincronização compatível para seleções de plugins e configurações preparadas. A publicação ocorre por seção, em vez de um envio separado para cada linha. As configurações mostram nomes das chaves alteradas sem expor valores; conflitos permitem escolher a versão local ou do Cloud, não mesclar campos arbitrariamente. Leia a ação da seção e o modo de sincronização selecionado antes de publicar.</p><p>Overlays do Cloud usam o fluxo de criação/revisão da <a href="./../overlays/">biblioteca/editor</a>. Um adaptador compartilhado Changes de overlays não está disponível nesta versão base.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, status e recuperação <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “Resultado esperado, status e recuperação”">​</a></h2><p>A comparação local de automações e o compartilhamento nativo condicionado às capacidades estão disponíveis nas respectivas áreas. Operações com efeitos remotos dependem do serviço; isso não implica aceitação em produção. Se uma revisão ficar desatualizada, atualize e compare novamente. Se o resultado não estiver confirmado, inspecione as informações de status/diário antes de criar outra operação. Nunca trate um tempo limite como prova de que nada mudou.</p>`,12),t(p,{id:`changes`,locale:`pt`,title:`Demonstração: Cloud`}),c[1]||=o(`h2`,{id:`operational-details`,tabindex:`-1`},[r(`Detalhes de operação `),o(`a`,{class:`header-anchor`,href:`#operational-details`,"aria-label":`Permalink to “Detalhes de operação”`},`​`)],-1),c[2]||=o(`p`,null,`Antes de preparar/migrar v1 → v2, faça backup e coordene versões compatíveis em todos os dispositivos. No setup prepare, confira compatibilidade e visualize; revise contagens de seleção, pendências, conflitos e itens só-v1, sem presumir sincronização. Exigir cabeçalho de época é irreversível para escritas v2 de toda a conta e pode rejeitar dispositivos antigos. Timeout da barreira é ambíguo; repeti-la avança novamente. Atualize estado de época/migração e prévia antes de agir. Ler época não comprova escritas anteriores concluídas.`,-1),c[3]||=o(`p`,null,`A recuperação depende do modo: Changes de Events/Actions compara referências locais, sem escrita Cloud. Para Variables/Plugins revisados, atualize comparações expiradas e confira revisão, conta e inventário. Se faltarem plugins, use revisão/reparo de inventário do setup e outra prévia. Para intenção incerta, preserve ID/evidência e consulte histórico/estado; recuperação técnica exige nova revisão das entradas congeladas e revisão Cloud. Retomar essa intenção não envia escrita remota por si só. Pare sem criar mutação substituta se não puder reconciliar.`,-1)])}var d=s(l,[[`render`,u]]);export{c as __pageData,d as default};